package phash_test

import (
	"bufio"
	"os"
	"strings"
	"testing"

	"github.com/lbe/go-image-phash/phash"
)

// TestBitsToHexMatchesImagePHashB2h verifies that BitsToHex produces the same
// uppercase hex strings as Image::PHash 0.3's b2h for golden bit strings,
// including lengths not divisible by 4. The goldens in
// ../testdata/b2h/golden.txt were generated by running the verbatim b2h
// subroutine from lib/Image/PHash.pm (v0.3) over each input.
func TestBitsToHexMatchesImagePHashB2h(t *testing.T) {
	f, err := os.Open("../testdata/b2h/golden.txt")
	if err != nil {
		t.Fatalf("open golden vectors: %v", err)
	}
	t.Cleanup(func() {
		if err := f.Close(); err != nil {
			t.Errorf("close golden vectors: %v", err)
		}
	})

	type goldenCase struct {
		bits string
		want string
	}
	var cases []goldenCase
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		fields := strings.Split(line, "\t")
		if len(fields) != 2 {
			t.Fatalf("malformed golden line %q", line)
		}
		cases = append(cases, goldenCase{bits: fields[0], want: fields[1]})
	}
	if err := sc.Err(); err != nil {
		t.Fatalf("scan golden vectors: %v", err)
	}
	if len(cases) == 0 {
		t.Fatal("no golden cases loaded")
	}

	for _, c := range cases {
		got := phash.BitsToHex(c.bits)
		if got != c.want {
			t.Errorf("BitsToHex(%q) = %q, want %q (Image::PHash b2h)", c.bits, got, c.want)
		}
	}
}
